                ReferenceEquals(baseline.EndpointRead.Task, session.StatusPrivateDeleteEndpointBefore) &&
                baseline.Reader.OwnsStatusPrivateConnectionDeleteRead(baseline.Proof, baseline.Window,
                    baseline.Binding, baseline.Task));
