    public ValueTask DisposeAsync()
    {
        if (statusDeniedVaultRecoverProfile) return DisposeDeniedVaultRecoverAsync();
        if (statusDeniedVaultUpdateProfile) return DisposeDeniedVaultUpdateAsync();
        TaskCompletionSource completion;
        lock (gate)
        {
            if (disposal is not null) return new(disposal.Task);
            if (statusDeniedPrivateDeleteProfile)
                foreach (var session in sessions.Values.Where(s => !s.Closed && s.Active == 0))
                {
                    try
                    {
                        if (deniedPrivateDeleteRuns[session].Pending is not null)
                            PersistDeniedPrivateDelete(session);
                        if (session.Plan is not null && provisioner.HasStatusDeniedPrivateConnectionDeletePersistence(session.Plan))
                            provisioner.RetryStatusDeniedPrivateConnectionDeletePersistence(session.Plan);
                        if (session.Plan is not null && session.Endpoints?.HasStatusDeniedPrivateConnectionDeletePersistence(session.Plan) == true)
                            session.Endpoints.RetryStatusDeniedPrivateConnectionDeletePersistence(session.Plan);
                    }
                    catch (Exception) { deniedPrivateDeleteDisposePublicationFailed = true; }
                }
            if (statusDeniedNotificationDeleteProfile)
                foreach (var session in sessions.Values.Where(s => s.Active == 0 && s.DeniedNotificationDeletePending is not null))
                    try { RetryStatusDeniedNotificationDeletePersistence(session.Selector); }
                    catch (Exception) { deniedPrivateDeleteDisposePublicationFailed = true; }
            disposed = true;
            completion = disposal = new(TaskCreationOptions.RunContinuationsAsynchronously);
            if (active == 0) drained.TrySetResult();
        }
        _ = PendingProfile || statusSucceededDeleteVaultProfile || statusSucceededDeleteVaultIndependentProfile || statusSucceededDeleteVaultCancellationProfile ? Drain(completion) :
            profile is Profile.OriginalPrivateConnectionDelete or Profile.PrivateConnectionDeleteCleanup
            ? DrainPrivateConnectionDelete(completion) : profile is Profile.OriginalPrivateConnectionUpdate or Profile.PrivateConnectionUpdateCleanup
            ? DrainPrivateConnectionUpdate(completion) : profile is Profile.OriginalVaultRecover or Profile.RecoverVaultCleanup
            ? DrainRecoverVault(completion) : profile is Profile.OriginalVaultCreateOrUpdate or Profile.CreateOrUpdateVaultCleanup
            ? DrainCreateOrUpdateVault(completion) : profile == Profile.StatusFamily ? Drain(completion) :
            profile is Profile.OriginalVaultPurge or Profile.PurgeDeletedVaultCleanup
                ? DrainPurgeDeletedVault(completion) : DrainDeleteVault(completion);
